//! Official standalone System constructor checked against independent wire facts.

#![no_std]
#![forbid(unsafe_code)]

use solana_address::Address;

/// Validates official serialization, program identity, account order and roles.
///
/// The fixed bytes are manually transcribed from the independently pinned Dart
/// schema, never generated by the official constructor being tested.
pub fn verify(corrupt: bool) -> Result<(), &'static str> {
    let payer = Address::new_from_array([0x11; 32]);
    let account = Address::new_from_array([0x22; 32]);
    let owner = Address::new_from_array([0x33; 32]);
    let instruction = solana_system_interface::instruction::create_account(
        &payer,
        &account,
        0x0102_0304_0506_0708,
        0x1112_1314_1516_1718,
        &owner,
    );
    let mut expected = [0x33; 52];
    expected[..20].copy_from_slice(&[
        0, 0, 0, 0, 8, 7, 6, 5, 4, 3, 2, 1, 24, 23, 22, 21, 20, 19, 18, 17,
    ]);

    if corrupt {
        expected[0] = 1;
    }

    if instruction.data != expected {
        return Err("CreateAccount serialized bytes mismatch");
    }

    if instruction.program_id.to_bytes() != [0; 32] {
        return Err("System Program address mismatch");
    }

    if instruction.accounts.len() != 2 {
        return Err("account count mismatch");
    }

    for (meta, address) in instruction.accounts.iter().zip([payer, account]) {
        if meta.pubkey != address || !meta.is_signer || !meta.is_writable {
            return Err("account order or privileges mismatch");
        }
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    /// Both success and the corruption detector execute the real constructor.
    #[test]
    fn official_create_account_matches_independent_fixture() {
        assert_eq!(super::verify(false), Ok(()));
        assert_eq!(
            super::verify(true),
            Err("CreateAccount serialized bytes mismatch")
        );
    }
}
